// Generic template that works with most pointer types
template<typename T>
void processPointer(T* ptr) { /* implementation for generic pointers */ }

// Specialization to delete the template for void pointers
template<>
void processPointer<void>(void* ptr) = delete;

// Overload to delete the template for char pointers
void processPointer(char* ptr) = delete;

void test() {
    int x = 10;
    int* pInt = &x;
    processPointer(pInt); // OK: instantiates and calls generic template

    void* pVoid = pInt;
    // processPointer(pVoid); // Compile Error: calls deleted void* specialization

    char c = 'a';
    // processPointer(&c);  // Compile Error: calls deleted char* overload
}
